// Pitch in Hz, duration in ms const int notes[][2] = { {Pretend there’s a series of notes and durations here, condensed for readability}};
void delay(uint32_t ms) { TIM2_reg-&gt;ARR = 2000000/(1000*(40))-1; //default delay will be 1000 Hz TIM2_reg-&gt;CNT = 0; for (int i = 1; i &lt;= ms; i++) { while(!(TIM2_reg-&gt;SR & 1)) {} TIM2_reg-&gt;SR &= ~(1&lt;&lt;0); } }
void play(int frq, int ms) { TIM2_reg-&gt;ARR = 2000000/(frq*(40))-1; TIM2_reg-&gt;CNT = 0; for (uint32_t i = 1; i &lt;= ms; i++) { while(!(TIM2_reg-&gt;SR & 1)) {} TIM2_reg-&gt;SR &= ~(1&lt;&lt;0); GPIOB_reg-&gt;ODR ^= (1&lt;&lt;SPK); //get TIM2_reg- as in it? lay lay(int ms) rest? void { }&gt;CR1 &= ~0x01; //Disable Timer since that’s the CEN bit GPIOB_reg-&gt;ODR = ~(1 &lt;&lt; SPK); delay(ms); }
int main(void) {
int i = 0;

RCC_reg-&gt;AHB2ENR |= (1 &lt;&lt; 1); //Bit 1 is GPIOBEN, fits our GPIO B specs
RCC_reg-&gt;APB1ENR1 |= (1 &lt;&lt; 0); //Bit 0 is TIM2EN

GPIOB_reg-&gt;MODER &= ~(3 &lt;&lt; (SPK * 2)); //Speaker general purpose output
GPIOB_reg-&gt;MODER |= (1 &lt;&lt; (SPK * 2));

TIM2_reg-&gt;PSC = 39;  //Prescaler divider const. for frequency calcs 
TIM2_reg-&gt;CR1 |= 1; //CEN as specified before

while(!(notes[i][0] == 0 && notes[i][1] == 0)) {
    int frq = notes[i][0]; //assigning freq to the first element
    int del = notes[i][1]; //assigning delay duration to second element
    if (frq == 0) {
    //lay(del);
    delay(del*2);
}
else {
    uint32_t ms = frq*del/500;
    play(frq, ms*0.80);
    //TIM2_reg-&gt;CR1 |= (1 &lt;&lt; 0); //Enable CEN
    delay(ms);
}
i++;
GPIOB_reg-&gt;ODR = ~(1 &lt;&lt; SPK); //Toggling to create the square wave
}
